function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

const body = $json.body || {};
const avatar = String(body.avatar || '').trim();
const scene = String(body.scene || '').trim();
const assetType = String(body.assetType || body.asset_type || 'raw-image').trim();
const status = String(body.status || '').trim();
const baseUrl = String(body.baseUrl || body.base_url || 'http://192.168.0.194:9000').replace(/\/$/, '');

const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;

if (!slugRegex.test(avatar) || !slugRegex.test(scene) || !slugRegex.test(assetType)) {
  return {
    json: {
      skipQuery: true,
      ok: false,
      resolved: false,
      statusCode: 400,
      error: 'avatar, scene and assetType are required and must be slug-like values',
      request: { avatar: avatar || null, scene: scene || null, assetType: assetType || null }
    }
  };
}

const statusPredicate = status
  ? `status = ${sql(status)}`
  : `COALESCE(status, '') IN ('canonical', 'selected', 'raw')`;

const query = `
SELECT
  asset_id,
  sha256,
  avatar,
  asset_type,
  scene,
  bucket,
  object_path,
  mime_type,
  status,
  is_canonical,
  canonical_group,
  review_notes,
  metadata,
  created_at
FROM canonical_asset_registry
WHERE avatar = ${sql(avatar)}
  AND scene = ${sql(scene)}
  AND asset_type = ${sql(assetType)}
  AND ${statusPredicate}
ORDER BY
  CASE
    WHEN COALESCE(is_canonical, false) = true OR status = 'canonical' THEN 1
    WHEN status = 'selected' THEN 2
    WHEN status = 'raw' THEN 3
    ELSE 4
  END,
  created_at DESC
LIMIT 1;
`;

return {
  json: {
    skipQuery: false,
    query,
    avatar,
    scene,
    assetType,
    status,
    baseUrl
  }
};

const params = $('Build Resolve Query').first().json;
const row = $input.first()?.json ?? {};

if (!row.asset_id || !row.bucket || !row.object_path) {
  return [{
    json: {
      ok: false,
      resolved: false,
      statusCode: 404,
      error: 'No asset found for requested avatar, scene and assetType',
      request: {
        avatar: params.avatar,
        scene: params.scene,
        assetType: params.assetType,
        status: params.status || null
      }
    }
  }];
}

const baseUrl = (params.baseUrl || 'http://192.168.0.194:9000').replace(/\/$/, '');

const asset = {
  assetId: row.asset_id,
  avatar: row.avatar,
  scene: row.scene,
  assetType: row.asset_type,
  status: row.status,
  isCanonical: row.is_canonical,
  canonicalGroup: row.canonical_group,
  bucket: row.bucket,
  objectPath: row.object_path,
  url: `${baseUrl}/${row.bucket}/${row.object_path}`,
  mimeType: row.mime_type,
  sha256: row.sha256,
  reviewNotes: row.review_notes,
  metadata: row.metadata,
  createdAt: row.created_at
};

return [{
  json: {
    ok: true,
    resolved: true,
    statusCode: 200,
    asset,
    ...asset
  }
}];
